export interface TouristPlace {
  name: string;
  category: 'Must-Visit' | 'Heritage' | 'Adventure' | 'Spiritual' | 'Lake & Nature' | 'Scenic View' | 'Offbeat & Camping' | 'Family & Leisure';
  pinCode?: string;
  type?: string;
  status?: string;
  district?: string;
  tehsil?: string;
  speciality?: string;
  famousFor?: string;
  whenDiscovered?: string;
  historicalBackground?: string;
  importantDates?: string;
  developer?: string;
  whatCanBeFound?: string;
  mainAttractions?: string;
  activities?: string;
  naturalSignificance?: string;
  historicalSignificance?: string;
  culturalSignificance?: string;
  religiousSignificance?: string;
  howToReach?: string;
  nearestTown?: string;
  nearestAirport?: string;
  nearestRailway?: string;
  roadConnectivity?: string;
  bestTime?: string;
  description: string;
  nearbyPlaces?: string;
  officialVerification?: string;
  sources?: string;
  image?: string;
}

export interface JKDistrictDestination {
  id: string;
  district: string;
  tagline: string;
  division: 'Kashmir Valley' | 'Jammu Division' | 'Chenab Valley' | 'Pir Panjal';
  listingsCount: number;
  rating: number;
  reviewsCount: number;
  startingPrice: number; // in INR
  duration: string; // e.g., '3 - 5 Days'
  durationCategory: '1-3' | '4-7' | '8-14' | '15+';
  travelTypes: string[];
  budgetTier: 'budget' | 'mid' | 'luxury';
  bestSeason: string;
  altitude: string;
  image: string;
  shortDescription: string;
  overview: string;
  touristPlaces: TouristPlace[];
  coordinates: [number, number]; // [lng, lat]
  popularKey: string;
}

